#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    std::string rankTeams(std::vector<std::string>& votes) {
        int m = votes[0].size();
        std::vector<std::vector<int>> counts(26, std::vector<int>(m, 0));
        for (const auto& v : votes) {
            for (int i = 0; i < m; ++i) counts[v[i] - 'A'][i]++;
        }
        std::string teams = votes[0];
        std::sort(teams.begin(), teams.end(), [&](char a, char b) {
            int ia = a - 'A', ib = b - 'A';
            for (int i = 0; i < m; ++i) {
                if (counts[ia][i] != counts[ib][i]) return counts[ia][i] > counts[ib][i];
            }
            return a < b;
        });
        return teams;
    }
};

import java.util.*;

class Solution {
    public String rankTeams(String[] votes) {
        int m = votes[0].length();
        int[][] counts = new int[26][m];
        for (String v : votes) {
            for (int i = 0; i < m; i++) counts[v.charAt(i) - 'A'][i]++;
        }
        Character[] teams = new Character[m];
        for (int i = 0; i < m; i++) teams[i] = votes[0].charAt(i);
        Arrays.sort(teams, (a, b) -> {
            int ia = a - 'A', ib = b - 'A';
            for (int i = 0; i < m; i++) {
                if (counts[ia][i] != counts[ib][i]) {
                    return Integer.compare(counts[ib][i], counts[ia][i]);
                }
            }
            return Character.compare(a, b);
        });
        StringBuilder sb = new StringBuilder();
        for (char c : teams) sb.append(c);
        return sb.toString();
    }
}

var rankTeams = function(votes) {
    const m = votes[0].length;
    const counts = Array.from({ length: 26 }, () => new Int32Array(m));
    for (const v of votes) {
        for (let i = 0; i < m; i++) {
            counts[v.charCodeAt(i) - 65][i]++;
        }
    }
    const teams = votes[0].split("");
    teams.sort((a, b) => {
        const ia = a.charCodeAt(0) - 65, ib = b.charCodeAt(0) - 65;
        for (let i = 0; i < m; i++) {
            if (counts[ia][i] !== counts[ib][i]) return counts[ib][i] - counts[ia][i];
        }
        return a < b ? -1 : 1;
    });
    return teams.join("");
};
